namespace BobbyBoi;
sealed partial class Pet {
 void WorldMenu(){ExpansionMenu();var actions=new ToolStripMenuItem("World actions");
  void Add(string text,Action action){actions.DropDownItems.Add(text,null,(_,_)=>{menu.Close();action();});}
  Add("Go Fishing",()=>RequestWorld(WorldEventKind.Fishing));Add("Build House",()=>RequestWorld(WorldEventKind.BuildHouse));Add("Visit House / Sleep",()=>RequestWorld(WorldEventKind.HouseVisit));Add("Summon Wolf",()=>{if(wolf!=null)WolfPopup(MouseButtons.Right);else RequestWorld(WorldEventKind.AdoptWolf);});Add("Find Treasure",()=>RequestWorld(WorldEventKind.Treasure));Add("Spawn Clones",()=>RequestWorld(WorldEventKind.Clone));Add("Summon Ender Dragon",()=>RequestWorld(WorldEventKind.Dragon));Add("Climb a Window",()=>RequestWorld(WorldEventKind.Climb));var cursor=new ToolStripMenuItem("Cursor prank (requires permission)");cursor.Click+=(_,_)=>RequestWorld(WorldEventKind.CursorPrank);actions.DropDownItems.Add(cursor);actions.DropDownItems.Add(new ToolStripSeparator());Add("Cancel current activity / boss",()=>{world.Clear();CancelWorld();});Add("Inventory and achievements",ShowWorldInventory);menu.Items.Add(actions);
  var debug=new ToolStripMenuItem("World debug");debug.DropDownItems.Add("Test fake death",null,(_,_)=>FakeDeath("BobbyBoi forgot gravity exists"));debug.DropDownItems.Add("Clear temporary world effects",null,(_,_)=>{CancelWorld();clones.Clear();treasure=null;worldParticles.Clear();});debug.DropDownItems.Add("Reset BobbyBoi World...",null,(_,_)=>ResetWorld());menu.Items.Add(debug);menu.Opening+=(_,_)=>{debug.Visible=data.World.Debug;cursor.Enabled=data.World.AllowCursor;};
 }
 void ObjectPopup(params (string Name,Action Action)[] items){objectMenu?.Dispose();objectMenu=new PetMenu{ClickSound=()=>Sfx("menu")};foreach(var item in items)objectMenu.Items.Add(item.Name,null,(_,_)=>{objectMenu.Close();item.Action();});objectMenu.StyleChildren();objectMenu.Show(Cursor.Position);}
 void WolfPopup(MouseButtons button){if(wolf==null)return;if(button==MouseButtons.Left){worldParticles.Burst(wolf.Feet-new System.Numerics.Vector2(0,45),Color.Pink,10,"?");wolf.Age=0;Sfx("tame");Say("good dog");return;}
  ObjectPopup(("Pet "+data.World.WolfName,()=>WolfPopup(MouseButtons.Left)),("Give Bone",()=>{data.Items.TryGetValue("Bone",out int bones);if(bones>0)data.Items["Bone"]=bones-1;worldParticles.Burst(wolf!.Feet-new System.Numerics.Vector2(0,45),Color.Pink,10,"?");SaveWorld();}), ("Sit",()=>SetWolfMode("Sit")),("Follow",()=>SetWolfMode("Follow")),("Sleep",()=>SetWolfMode("Sleep")),("Rename",RenameWolf),("Dismiss wolf",()=>{wolf=null;data.World.WolfAdopted=false;SaveWorld();}));
 }
 void SetWolfMode(string mode){if(wolf!=null){wolf.Mode=mode;data.World.WolfMode=mode;SaveWorld();}}
 void RenameWolf(){using var dialog=new Form{Text="Name your wolf",Size=new Size(320,160),StartPosition=FormStartPosition.CenterScreen,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false};var name=new TextBox{Text=data.World.WolfName,MaxLength=24,Dock=DockStyle.Top};var ok=new Button{Text="Save name",Dock=DockStyle.Bottom,DialogResult=DialogResult.OK};dialog.Controls.Add(name);dialog.Controls.Add(ok);dialog.AcceptButton=ok;if(dialog.ShowDialog()==DialogResult.OK){data.World.WolfName=name.Text;data.World.Normalize();SaveWorld();}}
 void HousePopup(){ObjectPopup(("Go inside / sleep",()=>RequestWorld(WorldEventKind.HouseVisit)),("Come outside",()=>{CancelWorld();x=data.World.HouseX-Width/2+110;y=data.World.HouseY-Height;}),("Sit on the roof",()=>{CancelWorld();x=data.World.HouseX-Width/2;onHouseRoof=true;y=data.World.HouseY-(data.World.HouseVariant==1?78:115)+10-Height;vy=0;Set(Act.Sit,6);}), ("Send wolf to bed",()=>SetWolfMode("Sleep")),("Store a gift in the house",()=>{var gift=data.Items.FirstOrDefault(i=>i.Value>0);if(gift.Key==null){Say("im broke");return;}data.Items[gift.Key]--;data.World.StoredItems.TryGetValue(gift.Key,out int old);data.World.StoredItems[gift.Key]=old+1;CountWorld("stored");Say("stored "+gift.Key);}), ("Take stored gifts",()=>{foreach(var item in data.World.StoredItems)AddWorldLoot(item.Key,item.Value);data.World.StoredItems.Clear();SaveWorld();Say("bank withdrawal");}),("Rebuild House",()=>RequestWorld(WorldEventKind.BuildHouse)));}
 void ChestPopup(){if(treasure==null)return;var t=treasure;var title=new Form{Text=t.Kind,Size=new Size(300,260),StartPosition=FormStartPosition.CenterScreen,FormBorderStyle=FormBorderStyle.FixedToolWindow};var list=new ListBox{Dock=DockStyle.Fill,BackColor=Color.FromArgb(39,48,36),ForeColor=Color.Beige,Font=new Font("Consolas",10)};foreach(var item in t.Items)list.Items.Add($"{item.Key} x{item.Value}");var take=new Button{Dock=DockStyle.Bottom,Height=34,Text=t.Claimed?"Already collected":"Take all",Enabled=!t.Claimed};take.Click+=(_,_)=>{if(!t.Claimed){foreach(var item in t.Items)AddWorldLoot(item.Key,item.Value);t.Claimed=true;t.Opening=1;CountWorld("chest");take.Text="Collected";take.Enabled=false;}};title.Controls.Add(list);title.Controls.Add(take);title.Show();}
 void ShowWorldInventory(){var f=new Form{Text="BobbyBoi - Inventory and achievements",Size=new Size(460,470),StartPosition=FormStartPosition.CenterScreen};var list=new ListBox{Dock=DockStyle.Fill,Font=new Font("Consolas",10),BackColor=Color.FromArgb(33,43,34),ForeColor=Color.Beige};foreach(var item in data.Items.Where(x=>x.Value>0).OrderBy(x=>x.Key))list.Items.Add($"{item.Key}  x{item.Value}");list.Items.Add("--- HOUSE STORAGE ---");foreach(var item in data.World.StoredItems)list.Items.Add($"{item.Key} x{item.Value}");list.Items.Add("--- ACHIEVEMENTS ---");foreach(var a in data.World.Achievements)list.Items.Add(a);list.Items.Add("--- COUNTERS ---");foreach(var c in data.World.Counters)list.Items.Add($"{c.Key}: {c.Value}");f.Controls.Add(list);f.Show();}
 void ResetWorld(){if(MessageBox.Show("Reset world objects, wolf, achievements and counters? Inventory and saved meme files stay.","Reset BobbyBoi World",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;CancelWorld();world.Clear();data.World=new WorldState();wolf=null;clones.Clear();treasure=null;worldParticles.Clear();houseMesh=null;standingPlatform=null;SaveWorld();}
 void WorldSettings(FlowLayoutPanel panel){ExpansionSettings(panel);panel.Controls.Add(new Label{Text="BOBBYBOI WORLD",Width=325,Height=32,ForeColor=Color.Goldenrod,Font=new Font("Segoe UI",10,FontStyle.Bold)});
  void Check(string text,bool value,Action<bool> apply){var c=new CheckBox{Text=text,Checked=value,Width=325,Height=text.Length>45?42:28};c.CheckedChanged+=(_,_)=>{apply(c.Checked);if(world.Busy&&!data.World.Enabled(world.Active!.Spec.Kind))CancelWorld();SaveWorld();};panel.Controls.Add(c);}
  Check("Automatic world activities",data.World.Automatic,v=>data.World.Automatic=v);Check("Fishing",data.World.Fishing,v=>data.World.Fishing=v);Check("House building and visits",data.World.Houses,v=>data.World.Houses=v);Check("Treasure chests",data.World.Chests,v=>data.World.Chests=v);Check("Render wolf companion",data.World.Companions,v=>data.World.Companions=v);Check("Temporary clones",data.World.Clones,v=>{data.World.Clones=v;if(!v)clones.Clear();});Check("Climb ordinary window edges",data.World.Climbing,v=>{data.World.Climbing=v;if(!v)standingPlatform=null;});Check("Rare Ender Dragon fights",data.World.Dragons,v=>data.World.Dragons=v);
  Check("Allow BobbyBoi to briefly move my real cursor",data.World.AllowCursor,v=>{data.World.AllowCursor=v;if(!v){cursorGrabbed=false;if(world.Active?.Spec.Kind==WorldEventKind.CursorPrank)CancelWorld();}});
  panel.Controls.Add(new Label{Text="Cursor: desktop only, max 1.2 seconds. Move your mouse quickly or press Escape to cancel. Ctrl+Alt+Backspace disables it. Cooldown: 5 minutes.",Width=320,Height=65,ForeColor=Color.DarkSeaGreen});
  panel.Controls.Add(new Label{Text="World event interval (seconds)",Width=320});var interval=new NumericUpDown{Minimum=30,Maximum=300,Value=Math.Clamp(data.World.EventInterval,30,300),Width=310};interval.ValueChanged+=(_,_)=>{data.World.EventInterval=(int)interval.Value;SaveWorld();};panel.Controls.Add(interval);
  Check("World debug menu and local event log",data.World.Debug,v=>data.World.Debug=v);
  var reset=new Button{Text="Reset BobbyBoi World...",Width=320,Height=32};reset.Click+=(_,_)=>ResetWorld();panel.Controls.Add(reset);
 }
}
